package io.github.syldegil.autotunnel;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
/** Per-interface values: never sum VPN, tethering or physical counters. */
final class TrafficTiles extends LinearLayout {
 TrafficTiles(Context c){super(c);setOrientation(VERTICAL);clear();}
 void clear(){removeAllViews();for(String g:new String[]{"Wi-Fi","USB","4G / 5G"})item(g,"En attente",Collections.emptyList());}
 void update(InspectorCollector.Sample s,InspectorHistory history){removeAllViews();Set<String> names=new TreeSet<>(s.indices.keySet());names.addAll(s.counters.keySet());names.addAll(s.types.keySet());for(String group:new String[]{"Wi-Fi","USB","4G / 5G"}){boolean found=false;for(String n:names){String role=s.types.getOrDefault(n,"");if(group.equals("4G / 5G")&&s.counters.containsKey("@mobile")&&!n.equals("@mobile"))continue;if(!group.equals(PhysicalRates.group(n,role)))continue;found=true;item(group,n.equals("@mobile")?"Mobile total":n+(role.isEmpty()?" · présumé":""),history.points(n,60000));}if(!found)item(group,"Non visible",Collections.emptyList());}}
 private void item(String group,String source,java.util.List<InspectorHistory.Point> points){Context c=getContext();LinearLayout box=DashboardUi.card(this);box.setPadding(AppStyle.dp(c,14),AppStyle.dp(c,12),AppStyle.dp(c,14),AppStyle.dp(c,8));LinearLayout head=DashboardUi.row(box);head.addView(new InspectorVisuals.Icon(c,group.equals("Wi-Fi")?"wifi":group.equals("USB")?"usb":"mobile",AppStyle.green(c)),new LayoutParams(AppStyle.dp(c,30),AppStyle.dp(c,30)));TextView title=DashboardUi.text(head,group,17,true);title.setPadding(AppStyle.dp(c,10),0,0,0);title.setLayoutParams(new LayoutParams(0,-2,1));DashboardUi.text(head,source,11,false);
  InspectorHistory.Point last=points.isEmpty()?null:points.get(points.size()-1);String rx=last==null?"—":InspectorHistory.rate(last.rx),tx=last==null?"—":InspectorHistory.rate(last.tx);LinearLayout values=DashboardUi.row(box);values.setPadding(0,AppStyle.dp(c,8),0,0);TextView down=DashboardUi.text(values,"↓ "+rx,20,true);down.setTextColor(AppStyle.green(c));down.setLayoutParams(new LayoutParams(0,-2,1));TextView up=DashboardUi.text(values,"↑ "+tx,20,true);up.setLayoutParams(new LayoutParams(0,-2,1));up.setTextColor(AppStyle.color(c,"#315fb7","#9bbdff"));box.addView(new Spark(c,points),new LayoutParams(-1,AppStyle.dp(c,32)));box.setContentDescription(group+", "+source+", réception "+rx+", envoi "+tx);
 }
 private static final class Spark extends View {final java.util.List<InspectorHistory.Point> points;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Spark(Context c,java.util.List<InspectorHistory.Point> values){super(c);points=values;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
 protected void onDraw(Canvas c){super.onDraw(c);p.setColor(AppStyle.color(getContext(),"#dce5ec","#2b3b4d"));p.setStrokeWidth(1);c.drawLine(0,getHeight()-3,getWidth(),getHeight()-3,p);if(points.isEmpty())return;long max=1,end=points.get(points.size()-1).elapsed;for(InspectorHistory.Point v:points)max=Math.max(max,Math.max(v.rx,v.tx));p.setStrokeWidth(AppStyle.dp(getContext(),2));for(int series=0;series<2;series++){p.setColor(series==0?AppStyle.green(getContext()):AppStyle.color(getContext(),"#315fb7","#9bbdff"));InspectorHistory.Point old=null;float ox=0,oy=0;for(InspectorHistory.Point v:points){long value=series==0?v.rx:v.tx;if(value<0){old=null;continue;}float x=getWidth()*(1-(end-v.elapsed)/60000f),y=getHeight()-3-(getHeight()-6)*value/(float)max;if(old!=null&&v.elapsed-old.elapsed<=15000)c.drawLine(ox,oy,x,y,p);c.drawCircle(x,y,2,p);old=v;ox=x;oy=y;}}}
 }
}
